void setZeroes(int**m,int rows,int*cols){int n=cols[0],row0=0,col0=0;for(int j=0;j<n;j++)if(m[0][j]==0)row0=1;for(int i=0;i<rows;i++)if(m[i][0]==0)col0=1;for(int i=1;i<rows;i++)for(int j=1;j<n;j++)if(m[i][j]==0)m[i][0]=m[0][j]=0;for(int i=1;i<rows;i++)for(int j=1;j<n;j++)if(m[i][0]==0||m[0][j]==0)m[i][j]=0;if(row0)for(int j=0;j<n;j++)m[0][j]=0;if(col0)for(int i=0;i<rows;i++)m[i][0]=0;}
